-- The classification of the numbers held in the model's code (03_code_data.sql), kept by hand: where each comes from
-- (status, source: CAPRI gms paths are relative to allgms/), and whether it belongs in the code (action).

CREATE TABLE code_data_status (
    file VARCHAR NOT NULL,
    scope VARCHAR NOT NULL,
    value DOUBLE NOT NULL,
    status VARCHAR NOT NULL CHECK (status IN ('capri', 'capri-data', 'literature', 'physical', 'numerical', 'capri-mod', 'technical', 'open')),
    action VARCHAR NOT NULL CHECK (action IN ('keep', 'to-data', 'to-setting', 'register', 'check')),
    source VARCHAR,
    note VARCHAR,
    PRIMARY KEY (file, scope, value)
);

-- rule: every number in the model's code has its classification (run tools/check/make_code_data.py, then classify)
SELECT d.file, d.scope, d.value, d.lines FROM code_data d LEFT JOIN code_data_status s USING (file, scope, value) WHERE s.file IS NULL;
-- rule: no classification without its number (the code moved: drop or re-key the row)
SELECT s.file, s.scope, s.value FROM code_data_status s LEFT JOIN code_data d USING (file, scope, value) WHERE d.file IS NULL;
